use maxt_bindings_common::schema::{Schema, TaggedUnion, Type};

pub(crate) const HEADER: &str =
    "// Generated by `cargo run -p maxt-bindings-codegen`. Do not edit.\n";

pub(crate) fn lower_camel(value: &str) -> String {
    let mut characters = value.chars();
    match characters.next() {
        Some(first) => first.to_ascii_lowercase().to_string() + characters.as_str(),
        None => String::new(),
    }
}

pub(crate) fn render(schema: &Schema) -> String {
    let mut output = String::from(HEADER);
    output.push_str("\nexport type DecimalWire = string;\nexport type TimestampWire = string;\n");
    output.push_str("export type MarketKindWire = \"spot\" | \"perpetual\";\n\n");
    for record in &schema.records {
        output.push_str(&format!(
            "export interface {}{} {{\n",
            record.name,
            type_parameters(record.type_parameters)
        ));
        for field in &record.fields {
            output.push_str(&format!(
                "  readonly {}: {};\n",
                field.name,
                ts_type(&field.ty)
            ));
        }
        output.push_str("}\n\n");
    }
    for union in &schema.unions {
        render_union(&mut output, union);
    }
    output.push_str(&format!(
        "export const EXCHANGES = [{}] as const;\n",
        quoted(&schema.exchanges)
    ));
    output.push_str(&format!(
        "export const NATIVE_API_VERSION = {} as const;\n",
        schema.native_api_version
    ));
    output.push_str(&format!(
        "export const FEATURES = [{}] as const;\n",
        quoted(&schema.features)
    ));
    output.push_str(&format!(
        "export const ERROR_VARIANTS = [{}] as const;\n",
        quoted(schema.errors)
    ));
    output.push_str(&format!(
        "export const ADAPTER_OPERATIONS = [{}] as const;\n",
        quoted(
            schema
                .adapter_operations
                .iter()
                .map(|operation| operation.language_name)
        )
    ));
    output.push_str(&format!(
        "export const CLIENT_MEMBERS = [{}] as const;\n",
        quoted(schema.client_members)
    ));
    output.push_str("export const PROVIDER_METHODS = {\n");
    for provider in schema.providers {
        output.push_str(&format!(
            "  {}: [{}],\n",
            provider.exchange,
            quoted(provider.methods.iter().map(|method| method.name))
        ));
    }
    output.push_str("} as const;\nexport const PROVIDER_CONSTRUCTORS = {\n");
    for provider in schema.providers {
        output.push_str(&format!(
            "  {}: [{}],\n",
            provider.exchange,
            quoted(provider.constructors)
        ));
    }
    output.push_str("} as const;\n");
    output.push_str(&format!(
        "export const IDENTIFIERS = [{}] as const;\n",
        quoted(schema.identifiers)
    ));
    output.push_str(&format!(
        "export const MODELS = [{}] as const;\n",
        quoted(schema.models)
    ));
    let raw_native_exports = ["NATIVE_API_VERSION", "NativeClient", "createCustomClient"]
        .into_iter()
        .map(str::to_owned)
        .chain(schema.providers.iter().flat_map(|provider| {
            [
                provider.native_handle.trim_end_matches("Handle").to_owned(),
                provider.native_factory.to_owned(),
            ]
        }))
        .collect::<Vec<_>>();
    output.push_str(&format!(
        "export const RAW_NATIVE_EXPORTS = [{}] as const;\n",
        quoted(raw_native_exports)
    ));
    output.push_str(&format!(
        "export const RAW_NATIVE_CLIENT_MEMBERS = [{}] as const;\n",
        quoted(
            ["exchange", "supports"]
                .into_iter()
                .chain(schema.adapter_operations.iter().flat_map(|operation| {
                    operation
                        .client_methods
                        .iter()
                        .map(|method| method.native_name)
                }))
                .chain(["streamNext", "streamClose"])
        )
    ));
    output.push_str("export const RAW_PROVIDER_MEMBERS = {\n");
    for provider in schema.providers {
        output.push_str(&format!(
            "  {}: [{}],\n",
            provider.exchange,
            quoted(
                std::iter::once("client").chain(provider.methods.iter().map(|method| method.name))
            )
        ));
    }
    output.push_str("} as const;\n");
    output
}

fn quoted(values: impl IntoIterator<Item = impl AsRef<str>>) -> String {
    values
        .into_iter()
        .map(|value| format!("\"{}\"", value.as_ref()))
        .collect::<Vec<_>>()
        .join(", ")
}

fn ts_type(value: &Type) -> String {
    match value {
        Type::String => "string".to_owned(),
        Type::Boolean => "boolean".to_owned(),
        Type::Number => "number".to_owned(),
        Type::Decimal => "DecimalWire".to_owned(),
        Type::Timestamp => "TimestampWire".to_owned(),
        Type::Identifier(_) => "string".to_owned(),
        Type::Named(name) => (*name).to_owned(),
        Type::Optional(value) => format!("{} | null", ts_type(value)),
        Type::List(value) => format!("readonly {}[]", ts_type(value)),
        Type::Tuple(values) => format!(
            "readonly [{}]",
            values.iter().map(ts_type).collect::<Vec<_>>().join(", ")
        ),
    }
}

fn render_union(output: &mut String, union: &TaggedUnion) {
    output.push_str(&format!(
        "export type {}{} =\n",
        union.name,
        type_parameters(union.type_parameters)
    ));
    for (index, variant) in union.variants.iter().enumerate() {
        output.push_str(if index == 0 { "  | {" } else { "\n  | {" });
        output.push_str(&format!(" readonly kind: \"{}\";", variant.name));
        for field in &variant.fields {
            output.push_str(&format!(
                " readonly {}: {};",
                field.name,
                ts_type(&field.ty)
            ));
        }
        output.push_str(" }");
    }
    output.push_str(";\n\n");
}

fn type_parameters(values: &[&str]) -> String {
    if values.is_empty() {
        String::new()
    } else {
        format!("<{}>", values.join(", "))
    }
}
